        # A monochrome V has two diagonal boundary rays. Fill gaps between
        # their same-row endpoints, whether the V opens down or up.
        for apex_r in range(h):
            for apex_c in range(w):
                if grid[apex_r][apex_c] != color:
                    continue
                for direction in (-1, 1):
                    for depth in range(1, h):
                        r = apex_r + direction * depth
